import{_ as i,l,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"干涉仪对光栅编码器","description":"","frontmatter":{"title":"干涉仪对光栅编码器","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/interferometer-vs-encoder.md","filePath":"litho/interferometer-vs-encoder.md","lastUpdated":1789023840000}'),E={name:"litho/interferometer-vs-encoder.md"};function c(_,a,m,f,A,B){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="干涉仪对光栅编码器" tabindex="-1">干涉仪对光栅编码器 <a class="header-anchor" href="#干涉仪对光栅编码器" aria-label="Permalink to &quot;干涉仪对光栅编码器&quot;">​</a></h1><div class="epigraph"><p>工件台要知道自己在哪。激光干涉仪走光程，光栅编码器走尺。空气、阿贝臂和污染对两者的打法不同。</p><footer>—— 对照扫描投影机双频干涉仪与光栅编码器公开方案；套刻见 [litho-overlay](/litho/litho-overlay)</footer></div><p><a href="/litho/lens-contamination">上一课</a>把物镜表面污染收束，并点名下一单元是台子上的计量脏。本课打开「工件台与传感」：位置反馈选干涉仪还是编码器。不重写套刻预算分解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纳米套刻要求台位置在扫描全程可溯源。干涉仪把位移变成光程差，空气折射率（温、压、湿、CO₂）直接进读数，阿贝臂误差把俯仰变成横向。光栅尺把位移变成莫尔条纹，对空气不敏感，但对尺的热胀、安装与脏敏感。把「台不准」写成一种传感器，会选错补偿。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>量产机常编码器为主、干涉仪交叉校验或分轴。环境：干涉仪要气浴与波长补偿；编码器要尺温与清洁。校准把两种读数在同一轨迹上对起来，残差进套刻模型。</p>',7)),(e(),s(p,null,{default:r(()=>[h(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20IF%5B%22%E6%BF%80%E5%85%89%E5%B9%B2%E6%B6%89%E4%BB%AA%22%5D%20--%3E%20AIR%5B%22%E7%A9%BA%E6%B0%94%E6%8A%98%E5%B0%84%E7%8E%87%22%5D%0A%20%20ENC%5B%22%E5%85%89%E6%A0%85%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%20--%3E%20SCALE%5B%22%E5%B0%BA%E7%83%AD%20%2F%20%E8%84%8F%22%5D%0A%20%20IF%20--%3E%20POS%5B%22%E5%8F%B0%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20ENC%20--%3E%20POS%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">EUV 真空里空气项消失，干涉仪环境变了，但不等于编码器自动更好：磁浮台与热仍在。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>干涉相位 \\(\\Delta\\phi = 4\\pi n L/\\lambda\\)。\\(n\\) 漂等于假运动。光栅周期固定，误差来自尺本身与读头间隙。两者的噪声谱不同：气流是低频，读头振动可以更高频。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课调平：竖直方向另一套传感器，不要用同一套 XY 编码器冒充。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>干涉仪吃空气与阿贝臂；编码器吃尺与脏。</li><li>套刻补偿必须声明用了哪路反馈。</li><li>出处：扫描机位置计量通识；套刻课。</li></ul>',7))])}const b=i(E,[["render",c]]);export{T as __pageData,b as default};
